class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert (row, col) to position: row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count frequency of each color for each player
        player_color_count = [{} for _ in range(n)]

        # Populate the color counts
        for player, color in pick:
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winning_count = 0
        for player in range(n):
            max_count = max(player_color_count[player].values()) if player_color_count[player] else 0
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for rows
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare symmetric positions in row i
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for columns
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare symmetric positions in column j
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum of row flips and column flips
        return min(row_flips, col_flips)

def solve():
    N, K = map(int, input().split())
    functions = []
    for _ in range(N):
        A, B = map(int, input().split())
        functions.append((A, B))

    max_value = 0

    def backtrack(current_val, used_indices, remaining):
        nonlocal max_value

        if remaining == 0:
            max_value = max(max_value, current_val)
            return

        for i in range(N):
            if i not in used_indices:
                A, B = functions[i]
                new_val = A * current_val + B
                backtrack(new_val, used_indices + [i], remaining - 1)

    backtrack(1, [], K)
    return max_value

